ALTER TABLE `SERVICE_IMPACT_DETAILS` MODIFY COLUMN `SERVICE_IMPACT_DETAILS_ID_PK` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'Primary key - unique ID for each service impact detail record. Users may refer to this as: service impact detail ID, impact detail ID, record ID, or detail ID', MODIFY COLUMN `SERVICE_NAME` varchar(255) NOT NULL COMMENT 'Name of the impacted service. Users may refer to this as: service name, service, impacted service, or service title', MODIFY COLUMN `SERVICE_TYPE` varchar(100) NOT NULL COMMENT 'Type or category of the impacted service. Users may refer to this as: service type, service category, type of service, or service class', MODIFY COLUMN `STATUS` varchar(50) DEFAULT NULL COMMENT 'Current impact status of the service. Users may refer to this as: status, impact status, service status, or service impact state', MODIFY COLUMN `CREATION_TIME` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Timestamp when the record was created. Users may refer to this as: creation time, created at, created on, or record creation date', MODIFY COLUMN `MODIFICATION_TIME` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Timestamp when the record was last modified. Users may refer to this as: modification time, modified at, last updated, or update time', MODIFY COLUMN `L0` varchar(50) DEFAULT NULL COMMENT 'Geographical hierarchy level 0 (top-most level, e.g. country). Users may refer to this as: L0, level 0, geo level 0, or top geography', MODIFY COLUMN `L1` varchar(50) DEFAULT NULL COMMENT 'Geographical hierarchy level 1 (e.g. region/zone). Users may refer to this as: L1, level 1, geo level 1, or region', MODIFY COLUMN `L2` varchar(50) DEFAULT NULL COMMENT 'Geographical hierarchy level 2 (e.g. state/circle). Users may refer to this as: L2, level 2, geo level 2, or circle', MODIFY COLUMN `L3` varchar(50) DEFAULT NULL COMMENT 'Geographical hierarchy level 3 (e.g. district/city). Users may refer to this as: L3, level 3, geo level 3, or district', MODIFY COLUMN `L4` varchar(50) DEFAULT NULL COMMENT 'Geographical hierarchy level 4 (e.g. site/area). Users may refer to this as: L4, level 4, geo level 4, or site', MODIFY COLUMN `NODE_TYPE` varchar(50) DEFAULT NULL COMMENT 'Type of network node associated with the impact. Users may refer to this as: node type, network element type, NE type, or device type', MODIFY COLUMN `KPI_IMPACTED_NE` int DEFAULT NULL COMMENT 'Count of network elements impacted due to KPI degradation. Users may refer to this as: KPI impacted NE, KPI impacted count, KPI affected nodes, or KPI impacted elements', MODIFY COLUMN `DELETED` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Logical deletion flag (0 = active, 1 = deleted). Users may refer to this as: deleted, is deleted, soft delete flag, or active status', MODIFY COLUMN `ALARM_IMPACTED_NE` int DEFAULT NULL COMMENT 'Count of network elements impacted due to alarms. Users may refer to this as: alarm impacted NE, alarm impacted count, alarm affected nodes, or alarm impacted elements', MODIFY COLUMN `KPI_DATA` text COMMENT 'Raw KPI impact data details, typically stored as JSON. Users may refer to this as: KPI data, KPI details, KPI impact data, or KPI payload', MODIFY COLUMN `ALARM_DATA` text COMMENT 'Raw alarm impact data details, typically stored as JSON. Users may refer to this as: alarm data, alarm details, alarm impact data, or alarm payload', COMMENT = 'Table storing data for service impact details. Users may refer to this as: service impact details, service impact information, service impact data, or impact details';
